                    north: Math.min(90, south + (r + 1) * dLat + (r < rows - 1 ? overlapLat : 0)),
                    west: Math.max(-180, west + c * dLon - (c ? overlapLon : 0)),
                    east: Math.min(180, west + (c + 1) * dLon + (c < cols - 1 ? overlapLon : 0)),
