                                const a = route[i], b = route[i + 1];
                                if (!a || !b || a.lat == null || a.lon == null || b.lat == null || b.lon == null)
                                    continue;
                                const aKey = `${a.lat.toFixed(6)},${a.lon.toFixed(6)}`;
                                const bKey = `${b.lat.toFixed(6)},${b.lon.toFixed(6)}`;
