        page.innerHTML = `<div class="rv3-shell"><div class="rv3-head"><button class="btn-secondary" data-rv2="view" data-view="line">← Retour au roulement</button><span class="rv3-title">Outils avancés</span><button class="btn-secondary page-help-btn" data-page-help="rotations" type="button">❓ Aide</button><select data-rv3-select="rotation"><option value="">— choisir une ligne —</option>${mgr.rotations.map((r, i) => `<option value="${(0, html_text_js_1.htmlText)(r.id)}" ${r.id === this.selectedRotationId ? 'selected' : ''}>R${String(i + 1).padStart(2, '0')} · ${esc(r.name)}</option>`).join('')}</select><button class="btn-primary" data-rv2="new-rotation">+ Nouvelle ligne</button>${rot ? `<button class="btn-secondary" data-rv2="rename-rotation">Renommer</button><button class="btn-secondary" data-rv2="duplicate-rotation">Dupliquer</button><button class="btn-secondary" data-rv2="toggle-rotation">${rot.enabled ? '✓ Active' : '⏸ Inactive'}</button><button class="btn-secondary" data-rv2="delete-rotation">Supprimer</button><select data-rv3-select="calendar"><option value="">Circulation selon horaires</option>${cal.map((c, i) => `<option value="${(0, html_text_js_1.htmlText)(c.id)}" ${rot.calendarId === c.id ? 'selected' : ''}>#${i + 1} ${esc(c.name)}</option>`).join('')}</select>` : ''}<span class="rv3-spacer"></span><button class="btn-secondary" data-rv2="undo" ${this._history.length ? '' : 'disabled'} title="Annuler">↶</button><button class="btn-secondary" data-rv2="redo" ${this._future.length ? '' : 'disabled'} title="Rétablir">↷</button></div><div class="rv3-head" style="padding-top:6px;padding-bottom:6px"><div class="rv3-viewtabs"><button class="btn-secondary ${(0, html_text_js_1.htmlText)(this.activeView === 'fleet' ? 'active' : '')}" data-rv2="view" data-view="fleet">Vue générale</button><button class="btn-secondary ${(0, html_text_js_1.htmlText)(this.activeView === 'sheet' ? 'active' : '')}" data-rv2="view" data-view="sheet">Feuille de roulement</button><button class="btn-secondary ${(0, html_text_js_1.htmlText)(this.activeView === 'rotation' ? 'active' : '')}" data-rv2="view" data-view="rotation">Montage & opérations</button><button class="btn-secondary ${(0, html_text_js_1.htmlText)(this.activeView === 'material' ? 'active' : '')}" data-rv2="view" data-view="material">Journée matériel</button><button class="btn-secondary ${(0, html_text_js_1.htmlText)(this.activeView === 'table' ? 'active' : '')}" data-rv2="view" data-view="table">Liste des services</button></div>${this.activeView === 'material' ? `<label class="rv3-date-label">Journée <input type="date" data-rv3-select="date" value="${esc(this._selectedDateValue())}"></label>` : ''}${sheetPanels}<span class="rv3-spacer"></span>${rot && this.activeView !== 'fleet' ? `<span class="rv61-status ${(0, html_text_js_1.htmlText)(state)}">${state === 'ok' ? '✓ Exploitable' : state === 'warn' ? '⚠ À vérifier' : state === 'inactive' ? '⏸ Inactive' : '⛔ À corriger'}</span>` : '<span class="rv3-ok">Vue compagnie · horaires + matériel + opérations</span>'}</div>${this._renderControlDashboard(metrics, rot)}<div class="${(0, html_text_js_1.htmlText)(workClass)}"><aside class="rv3-library">${this._renderLibrary(rot)}</aside><main class="rv3-main">${mainContent}</main><aside class="rv3-inspector">${rot && this.activeView !== 'fleet' ? this._renderInspector(rot, issues, conflicts) : this._renderFleetInspector(metrics)}</aside></div>${rot && this.activeView !== 'fleet' ? this._renderSummary(rot, issues, conflicts) : ''}</div>`;
