        const rows = rots.map((r) => { const st = byId.get(r.id) || this._rotationUiState(r, m.allConflicts), services = (r.occurrences || []).map((o) => { const meta = this._occMeta(o), left = (Number(o.resolvedStartSec || 0) - min) * px, w = Math.max(48, (Number(o.resolvedEndSec || 0) - Number(o.resolvedStartSec || 0)) * px), from = this._stationCode(meta.from), to = this._stationCode(meta.to); return `<div class="rv4-fleet-service ${(0, html_text_js_1.htmlText)(st.key === 'bad' ? 'cancel' : st.key === 'warn' ? 'warn' : '')}" data-rv2="select-occ-rotation" data-rotation="${(0, html_text_js_1.htmlText)(r.id)}" data-occ="${(0, html_text_js_1.htmlText)(o.id)}" style="left:${(0, html_text_js_1.htmlText)(left)}px;width:${(0, html_text_js_1.htmlText)(w)}px" title="${esc(meta.rec?.number || '?')} • ${esc(meta.from?.name || '?')} → ${esc(meta.to?.name || '?')}"><b>${esc(meta.rec?.number || '?')}</b><div class="rv4-fleet-ends"><span>${(0, schedule_v2_model_js_1.formatScheduleClock)(o.resolvedStartSec || 0)} ${esc(from)}</span><span>${esc(to)} ${(0, schedule_v2_model_js_1.formatScheduleClock)(o.resolvedEndSec || 0)}</span></div></div>`; }).join(''); return `<div class="rv4-fleet-row"><div class="rv4-fleet-label" data-rv2="select-line" data-rotation="${(0, html_text_js_1.htmlText)(r.id)}"><b>${esc(r.name)}</b> <span class="rv61-status ${(0, html_text_js_1.htmlText)(st.key)}">${st.key === 'ok' ? '✓' : st.key === 'warn' ? '⚠' : st.key === 'inactive' ? '⏸' : '⛔'}</span><br><small>${esc(this._lineFormationText(r) || 'SANS MATÉRIEL')} • ${r.occurrences.length} service(s)</small></div><div class="rv4-fleet-track" style="width:${(0, html_text_js_1.htmlText)(width)}px">${services}</div></div>`; }).join('');
