        this.panelContent.querySelectorAll('[data-dir]').forEach((b) => b.addEventListener('click', () => { this.mode = b.dataset.dir === 'RETURN' ? schedule_v2_model_js_1.PathDirection.RETURN : schedule_v2_model_js_1.PathDirection.OUTBOUND; this.renderPanel(); this.draw(); this._setHint(this.mode === schedule_v2_model_js_1.PathDirection.RETURN ? 'RETOUR VERT actif. + VIA pour guider, clic gare pour ajouter un arrêt.' : 'ALLER BLEU actif. + VIA pour guider, clic gare pour ajouter un arrêt.'); }));
