    _updateHeader() { const rec = this._activeRecord(), ver = this._activeVersion(); const state = this.overlay.querySelector('#sv2-state'); state.textContent = stateLabel(ver.state); state.className = `sv2-state ${stateClass(ver.state)}`; this.overlay.querySelector('#sv2-title').textContent = `${rec.number || 'Sans numéro'} ${rec.name || ''}`; const rm = this.overlay.querySelector('#sv2-route-mode'); rm.textContent = this.mode === schedule_v2_model_js_1.PathDirection.RETURN ? 'RETOUR' : 'ALLER'; rm.className = `sv2-route-mode ${this.mode === schedule_v2_model_js_1.PathDirection.RETURN ? 'ret' : 'out'}`; }
