    if (passenger && freight)
        details.add('role-mixed');
    if (item.isDrivingTrailer || /driving trailer|steuerwagen|cab car|voiture pilote/.test(txt))
        details.add('role-driving-cab');
    if (service)
        details.add('role-service');
