        <div>
          <b>${(0, html_text_js_1.htmlText)(s.name)}</b> — ${(0, html_text_js_1.htmlText)(s.fromStationName)} → ${(0, html_text_js_1.htmlText)(s.toStationName)}<br>
          <span>${Math.round(s.distance)} km · Vmax ${s.maxSpeed} km/h · ${s.electrified !== false ? 'électrifié' : 'non électrifié'}</span>
        </div>
        <button class="btn-sm danger" data-delete-sillon="${(0, html_text_js_1.htmlText)(s.id)}" title="Supprimer le sillon">✕</button>
      </div>
