        this.canvas.addEventListener('wheel', (e) => { e.preventDefault(); const r = this.canvas.getBoundingClientRect(); this.tileMap.applyZoom(e.deltaY < 0 ? 1 : -1, e.clientX - r.left, e.clientY - r.top); this.draw(); this._queueVisibleEngineOsm(false); }, { passive: false });
        this.canvas.addEventListener('mousedown', (e) => this._beginMapPointer(e));
