        this.form = { name: '', startDate: today, endDate: tomorrow, startTime: '22:00', endTime: '05:00', recurrence: 'daily', daysOfWeek: [0, 1, 2, 3, 4, 5, 6], scope: 'sections', station: null, affectsTraffic: true, stationImpact: 'stop', stationSpeedLimit: 40 };
        this._setStatus(`Technologie ${WORKS_SC_TECH} active. Ajoutez une section puis cliquez la gare A.`);
